local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'

local Text = CS.UnityEngine.UI.Text
local Image = CS.UnityEngine.UI.Image
local ImageAlterable = CS.Engine.UI.ImageAlterable
local Button = CS.UnityEngine.UI.Button
local phoneComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PhoneComponent)

local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local UIFeelingFavorabilityFigureRoleNode = "Game.UI.Phone.Likability.UIFeelingFavorabilityFigure.UIFeelingFavorabilityFigureRoleNode"

---@class UIFeelingFavorabilityFigureDialog
local UIFeelingFavorabilityFigureDialog = Class("UIFeelingFavorabilityFigureDialog")

function UIFeelingFavorabilityFigureDialog:__init() 
    self._catId = nil
    self._allCardId = {}
    self._curSelectId = nil         --当前选择的id
end

function UIFeelingFavorabilityFigureDialog:__delete()
    self._catId = nil
    self._allCardId = {}
    self._curSelectId = nil
end

function UIFeelingFavorabilityFigureDialog:Awake()
    local argument = self.controller.Argument.parameters
    if not argument then
        return
    end
    self._catId = checkNumber(argument.catId) 
    local vo = PhoneUtils.GetCatVo(self._catId)
    if not vo then
        return
    end

    self:InitData()
    self:FillSelf()
end

function UIFeelingFavorabilityFigureDialog:InitData()
    self._allCardId = CardUtils.GetAllCardIdGetByRoleId(self._catId)
end

function UIFeelingFavorabilityFigureDialog:FillSelf()
    SetButtonAction(self.bg, function()
        UIModule.CloseDialog(self.controller)
    end)
    self.LoopViewChat:InitGridView(#self._allCardId, Bind(self, self.OnGetCellByIndex))

    CfUtils.FillText(self.FontStyleButton.transform:Find("Text"), localize("变更"))
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnChange))
end

function UIFeelingFavorabilityFigureDialog:OnGetCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local id = self._allCardId[index + 1]
    local cell = listView:NewListViewItem("itemcel")
    local scr = CfUtils.GetLuaScr(cell, UIFeelingFavorabilityFigureRoleNode)
    if scr then
        scr:Refresh(id, self._catId, function()
            if checkNumber(self._curSelectId) ~= checkNumber(id) then
                if self._curSelectId then
                    local lastGo = self.LoopViewChat:GetShownItemByItemIndex(table.indexof(self._allCardId, checkString(self._curSelectId)) - 1)
                    if lastGo then
                        local lastScr = CfUtils.GetLuaScr(lastGo, UIFeelingFavorabilityFigureRoleNode)
                        if lastScr then
                            lastScr:FillUnSelect()
                        end
                    end
                end
    
                self._curSelectId = checkString(id)
                scr:FillSelect()
            end
        end)
        if checkNumber(self._curSelectId) ~= checkNumber(id) then
            scr:FillUnSelect()
        else
            scr:FillSelect()
        end
    end
    return cell
end

--变更形象
function UIFeelingFavorabilityFigureDialog:OnBtnChange()
    phoneComp:PhoneSaveSkinReq(self._catId, self._curSelectId, function()
        UIModule.BackDialog()
    end)
end

function UIFeelingFavorabilityFigureDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CfUtils.SetTopCommonActive(true, false)
    end))
    return coWait
end

function UIFeelingFavorabilityFigureDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIFeelingFavorabilityFigureDialog
